const materials={};function mat(c,extra={}){const key=c+JSON.stringify(extra);return materials[key]??=new THREE.MeshStandardMaterial({color:c,roughness:.87,...extra});}
function mesh(geometry,color,parent=roomGroup,extra={}){const m=new THREE.Mesh(geometry,mat(color,extra));m.castShadow=true;m.receiveShadow=true;parent.add(m);return m;}
function box(w,h,d,x,y,z,c,parent=roomGroup,extra){const m=mesh(new THREE.BoxGeometry(w,h,d),c,parent,extra);m.position.set(x,y,z);return m;}
function cyl(rt,rb,h,x,y,z,c,parent=roomGroup,n=8,extra){const m=mesh(new THREE.CylinderGeometry(rt,rb,h,n),c,parent,extra);m.position.set(x,y,z);return m;}
function gem(x,y,z,c,size=.5,parent=roomGroup){const m=mesh(new THREE.OctahedronGeometry(size),c,parent,{metalness:.15,roughness:.2,emissive:c,emissiveIntensity:.23});m.position.set(x,y,z);animated.push({m,y,spin:true});return m;}
function label(text,x,y,z,size=1.2,color='#f2e4b6',parent=roomGroup){const c=document.createElement('canvas');c.width=512;c.height=128;const ctx=c.getContext('2d');ctx.font='500 64px Georgia';c.width=Math.max(128,Math.ceil(ctx.measureText(text).width+40));ctx.font='500 64px Georgia';ctx.textAlign='center';ctx.textBaseline='middle';ctx.shadowColor='#153c32';ctx.shadowBlur=9;ctx.fillStyle=color;ctx.fillText(text,c.width/2,64);const tex=new THREE.CanvasTexture(c);const sprite=new THREE.Sprite(new THREE.SpriteMaterial({map:tex,depthWrite:false,transparent:true}));sprite.position.set(x,y,z);sprite.scale.set(size*c.width/128,size,1);parent.add(sprite);return sprite;}
