function arch(x,z,open=false){const g=new THREE.Group();roomGroup.add(g);g.position.set(x,0,z);box(.9,4.5,1, -1.7,2.25,0,'#b1bba1',g);box(.9,4.5,1,1.7,2.25,0,'#b1bba1',g);box(4.3,.65,1.2,0,4.65,0,'#c9cbb0',g);box(4.7,.18,1.4,0,5.08,0,'#7f957f',g);const fill=box(2.5,3.9,.25,0,2,0,'#315b52',g,{emissive:'#60dfb7',emissiveIntensity:open?.7:.02,transparent:true,opacity:open?.38:1});for(let i=-1;i<=1;i++){box(.08,3.4,.08,i*.65,2,.2,open?'#b4f1c8':'#789786',g,{emissive:open?'#98e4b6':'#294d43',emissiveIntensity:.5});}label('✧',0,4.6,.68,.65,'#eee0ac',g);hit(x-1.7,z,.7);hit(x+1.7,z,.7);return {g,fill};}
function portalUpdate(){if(!door)return;const open=[state.balance,state.light,state.final][state.room];door.fill.material=mat(open?'#74c9ac':'#315b52',{emissive:open?'#65e1b4':'#203e38',emissiveIntensity:open?.6:.02,transparent:true,opacity:open?.38:1});}
function rubble(x,z){const m=mesh(new THREE.DodecahedronGeometry(.55),'#7f9783');m.position.set(x,.25,z);m.scale.set(1.6,.7,1);}
