 box(23,1.3,19,0,-.68,0,'#6f8873');box(22.7,.2,18.7,0,-.05,0,'#8ca184');
 for(let i=0;i<8;i++){const rock=mesh(new THREE.DodecahedronGeometry(2.4,0),'#4c6b60');rock.position.set(Math.cos(i*Math.PI/4)*8,-4.7,Math.sin(i*Math.PI/4)*6.8);rock.scale.y=1.8;}
 for(let x=-9;x<=9;x+=1.8)for(let z=-6.5;z<=7;z+=1.8){if(Math.abs(x)<2.4||Math.abs(z)<1.6){const tile=box(1.71,.1,1.71,x,.055,z,(Math.round(x+z)*7)%3?'#adb69a':'#b6bba0');tile.rotation.y=Math.sin(x*z)*.016;}}
