 box(1.8,1.3,.45,-4.3,.7,-6,'#8d9d80');label('⚖',-4.3,1.7,-5.8,.6);interact('memory',-4.3,-5,'Lire la pierre gravée',()=>panel('<div class="eyebrow">UNE TRACE DES GARDIENS</div><h2>Le retour</h2><p>« À ceux qui ont rendu les masques, les pierres ouvrent une nouvelle voie. »</p>'));
