function updateScale(){if(!scaleBeam)return;scaleBeam.rotation.z=(4-totalWeight(state))*.065;}
function balancePanel(){const sum=totalWeight(state);panel('<div class="eyebrow">LE MÉCANISME DE PIERRE</div><h2>La balance</h2><p>Plateau de gauche</p><div class="choices">'+[1,2,3].map(n=>state.inventory.includes('w'+n)?`<button data-weight="${n}" class="${state.weights.includes(n)?'active':''}" aria-pressed="${state.weights.includes(n)}">${n}</button>`:'').join('')+'</div><div class="measure">'+sum+' <span style="font-size:25px">'+(sum===4?'=':sum<4?'<':'>')+'</span> 4</div><p>'+(state.balance?'Le mécanisme est déverrouillé.':state.inventory.some(x=>x.startsWith('w'))?'Cliquez sur un poids pour le poser ou le reprendre.':'Votre sac ne contient aucun poids.')+'</p>');document.querySelectorAll('[data-weight]').forEach(b=>b.onclick=()=>{const n=Number(b.dataset.weight);state.weights=state.weights.includes(n)?state.weights.filter(x=>x!==n):[...state.weights,n];if(balanceSolved(state)&&!state.balance){state.balance=true;toast('La porte s’éveille.');chime();}updateScale();portalUpdate();save();inventory();balancePanel();});}
function mirror(x,z,index){const g=new THREE.Group();g.position.set(x,0,z);roomGroup.add(g);cyl(.65,.8,.4,0,.2,0,'#9aab8f',g);cyl(.1,.16,1.2,0,.8,0,'#c9bb87',g);const pane=new THREE.Group();pane.position.y=1.5;g.add(pane);box(1.65,1.2,.14,0,0,0,'#d5c58d',pane);box(1.4,.95,.16,0,0,.01,'#b9e4de',pane,{metalness:.7,roughness:.15,emissive:'#639f98',emissiveIntensity:.4});mirrorMeshes[index]=pane;hit(x,z,.8);interact('mirror'+index,x,z,'Tourner le miroir',()=>{state.mirrors[index]=1-state.mirrors[index];updateLight();if(lightSolved(state)&&!state.light){state.light=true;chime();toast('Le prisme a retrouvé sa lumière.');}portalUpdate();save();tone(360+index*90,.12);});}
function ray(a,b){const delta=new THREE.Vector3().subVectors(b,a),m=mesh(new THREE.CylinderGeometry(.035,.035,delta.length(),8),'#fff1b1',beamGroup,{emissive:'#fff0a4',emissiveIntensity:3,transparent:true,opacity:.9});m.position.copy(a).add(b).multiplyScalar(.5);m.quaternion.setFromUnitVectors(new THREE.Vector3(0,1,0),delta.normalize());}
function updateLight(){if(beamGroup){roomGroup.remove(beamGroup);disposeGroup(beamGroup);}beamGroup=new THREE.Group();roomGroup.add(beamGroup);mirrorMeshes.forEach((m,i)=>m.rotation.y=state.mirrors[i]?Math.PI/4:-Math.PI/4);const v=(x,z)=>new THREE.Vector3(x,1.5,z);ray(v(-6,0),v(0,0));if(state.mirrors[0]===0)ray(v(0,0),v(0,6));else{ray(v(0,0),v(0,-4.2));ray(v(0,-4.2),v(state.mirrors[1]===1?5.5:-5.5,-4.2));}}
