const starShape=new THREE.Shape();for(let i=0;i<10;i++){let a=i*Math.PI/5,r=i%2?.055:.13;let x=Math.sin(a)*r,y=Math.cos(a)*r;i?starShape.lineTo(x,y):starShape.moveTo(x,y);}starShape.closePath();const star=mesh(new THREE.ShapeGeometry(starShape),'#ffe29b',body,{side:THREE.DoubleSide});star.position.set(-.17,1.2,.22);
const legs=[],arms=[];for(let side of[-1,1]){const l=new THREE.Group();l.position.set(side*.18,.72,0);body.add(l);box(.24,.47,.25,0,-.23,0,'#344f4c',l);box(.27,.18,.38,0,-.5,.06,'#634b35',l);legs.push(l);const a=new THREE.Group();a.position.set(side*.43,1.35,0);body.add(a);box(.21,.45,.25,0,-.2,0,'#2eaaa0',a);box(.19,.2,.2,0,-.51,0,'#e6bf8d',a);arms.push(a);}
const shadow=mesh(new THREE.CircleGeometry(.52,24),'#203e35',scene,{transparent:true,opacity:.2,depthWrite:false});shadow.rotation.x=-Math.PI/2;shadow.position.y=.08;shadow.castShadow=false;
function toast(t){$('toast').textContent=t;$('toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('visible'),3100);}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));storageOK=true;}catch{storageOK=false;}$('saved').textContent=storageOK?'◇ Progression sauvegardée':'Sauvegarde indisponible dans ce navigateur';$('saved').style.opacity=1;clearTimeout(saveTimer);if(storageOK)saveTimer=setTimeout(()=>$('saved').style.opacity=0,2400);}
function inventory(){$('items').innerHTML=state.inventory.map(id=>`<button class="item ${state.weights.includes(Number(id.slice(1)))?'selected':''}" data-item="${id}" aria-label="${itemNames[id][1]}"><b>${itemNames[id][0]}</b><small>${itemNames[id][1]}</small></button>`).join('');document.querySelectorAll('[data-item]').forEach(b=>b.onclick=bagPanel);}
function panel(html){paused=true;keys.clear();$('panelContent').innerHTML=html;$('modal').hidden=false;$('close').focus();}
function closePanel(){$('modal').hidden=true;paused=false;keys.clear();}
function bagPanel(){panel('<div class="eyebrow">VOTRE INVENTAIRE</div><h2>Le sac de Néolias</h2><div class="choices">'+state.inventory.map(id=>`<div class="item"><b>${itemNames[id][0]}</b><small>${itemNames[id][1]}</small></div>`).join('')+'</div><p>'+(state.wand?'Un sceptre de lumière. À proximité d’un cristal, appuyez sur F pour projeter.':canCombine(state)?'Deux objets peuvent être assemblés.':state.inventory.length?'Les objets récoltés restent dans votre sac.':'Le sac est encore vide.')+'</p>'+(canCombine(state)?'<button class="primary" id="combine">Assembler le prisme et la branche <span>✧</span></button>':''));if($('combine'))$('combine').onclick=()=>{combine(state);save();inventory();if(state.room===2)objects.filter(o=>o.id.startsWith('target')).forEach(o=>o.title='Projeter la lumière · F');chime();bagPanel();toast('Sceptre de lumière assemblé');};}
function pauseMenu(){panel('<div class="eyebrow">NÉOLIAS II · VERSION 0.1</div><h2>Une pause dans les ruines</h2><p>Déplacez-vous avec ZQSD, WASD ou les flèches. Espace pour sauter, E pour interagir, I pour le sac et F pour projeter la lumière.</p><p>Votre progression est sauvegardée dans ce navigateur. Vous pouvez essayer autant de fois que vous voulez.</p><button class="primary" id="resume">Reprendre l’aventure <span>↗</span></button><button class="secondary" id="restart">Recommencer le passage</button>');$('resume').onclick=closePanel;$('restart').onclick=()=>{panel('<div class="eyebrow">RECOMMENCER</div><h2>Un nouveau départ ?</h2><p>La progression de ce prototype sera remise à zéro.</p><button class="primary" id="confirmReset">Recommencer</button><button class="secondary" id="cancelReset">Garder ma progression</button>');$('cancelReset').onclick=pauseMenu;$('confirmReset').onclick=()=>{state=freshState();save();enterRoom(0);};};}
function doInteract(){if(!started||paused)return;if(near&&!near.disabled)near.action();}
function jump(){if(started&&!paused&&jumpY===0){jumpV=6;tone(220,.08,.025);}}
function shoot(){if(!started||paused)return;if(!state.wand){toast('Aucun objet ne permet encore de projeter de la lumière.');return;}const targets=objects.filter(o=>o.id.startsWith('target')).map(o=>({o,d:Math.hypot(hero.position.x-o.x,hero.position.z-o.z)})).sort((a,b)=>a.d-b.d);const target=targets[0]?.d<5?targets[0].o:null;const start=hero.position.clone().add(new THREE.Vector3(0,1.3,0));const end=target?new THREE.Vector3(target.x,2,target.z):start.clone().add(new THREE.Vector3(Math.sin(body.rotation.y)*6,0,Math.cos(body.rotation.y)*6));const m=mesh(new THREE.SphereGeometry(.13,8,8),'#f5f1bd',scene,{emissive:'#eaffbe',emissiveIntensity:3});projectiles.push({m,start,end,t:0,target});tone(680,.18,.04);body.rotation.y=Math.atan2(end.x-start.x,end.z-start.z);}
function hitTarget(target){pulse=1;if(target.id==='target8'&&!state.final){state.final=true;save();portalUpdate();chime();toast('Le dernier passage s’est ouvert.');}else tone(310,.25);}
function finish(){state.seenEnd=true;save();paused=true;keys.clear();$('ending').hidden=false;$('touch').hidden=true;$('hud').hidden=true;}
function tone(freq,duration=.2,volume=.045){if(!soundOn)return;try{audioCtx??=new(window.AudioContext||window.webkitAudioContext)();audioCtx.resume();const o=audioCtx.createOscillator(),gain=audioCtx.createGain();o.type='sine';o.frequency.setValueAtTime(freq,audioCtx.currentTime);gain.gain.setValueAtTime(0,audioCtx.currentTime);gain.gain.linearRampToValueAtTime(volume,audioCtx.currentTime+.015);gain.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+duration);o.connect(gain);gain.connect(audioCtx.destination);o.start();o.stop(audioCtx.currentTime+duration+.05);}catch{}}
function chime(){[392,523,659,784].forEach((f,i)=>setTimeout(()=>tone(f,.7,.045),i*110));}
const isTouch=matchMedia('(pointer:coarse)').matches;document.body.classList.toggle('touch',isTouch);
$('play').textContent=state.inventory.length||state.balance?'Continuer l’aventure ↗':'Entrer dans les ruines ↗';
$('play').onclick=()=>{started=true;$('intro').hidden=true;$('hud').hidden=false;$('touch').hidden=!isTouch;if(!storageOK)save();};$('menu').onclick=()=>{if(started)pauseMenu();};document.querySelector('.brand').onclick=e=>{e.preventDefault();if(started)pauseMenu();};$('bagToggle').onclick=bagPanel;$('close').onclick=closePanel;$('modal').addEventListener('click',e=>{if(e.target===$('modal'))closePanel();});$('sound').onclick=()=>{soundOn=!soundOn;$('sound').textContent='Son : '+(soundOn?'oui':'non');tone(440,.25);};$('explore').onclick=()=>{$('ending').hidden=true;paused=false;$('hud').hidden=false;$('touch').hidden=!isTouch;};
window.addEventListener('keydown',e=>{const k=e.key.toLowerCase();if(['arrowup','arrowdown','arrowleft','arrowright',' '].includes(k))e.preventDefault();if(e.repeat)return;if(k==='escape'){if(!$('ending').hidden)return;if(paused)closePanel();else if(started)pauseMenu();return;}if(!started)return;if(k==='i'){if(paused)closePanel();else bagPanel();return;}if(paused)return;destination=null;keys.add(k);if(k==='e')doInteract();if(k==='f')shoot();if(k===' ')jump();});window.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));window.addEventListener('blur',()=>keys.clear());document.addEventListener('visibilitychange',()=>{keys.clear();clock.getDelta();});
document.querySelectorAll('[data-key]').forEach(b=>{b.onpointerdown=e=>{e.preventDefault();b.setPointerCapture(e.pointerId);keys.add(b.dataset.key);};b.onpointerup=b.onpointercancel=()=>keys.delete(b.dataset.key);});document.querySelectorAll('[data-action]').forEach(b=>b.onpointerdown=e=>{e.preventDefault();({jump,shoot,interact:doInteract})[b.dataset.action]();});
const groundRay=new THREE.Raycaster(),groundPlane=new THREE.Plane(new THREE.Vector3(0,1,0),0);$('world').addEventListener('pointerdown',e=>{if(!started||paused)return;const p=new THREE.Vector2(e.clientX/innerWidth*2-1,-e.clientY/innerHeight*2+1);groundRay.setFromCamera(p,camera);const v=new THREE.Vector3();if(groundRay.ray.intersectPlane(groundPlane,v)&&Math.abs(v.x)<10.2&&v.z>-7&&v.z<8)destination={x:v.x,z:v.z};});
function resize(){renderer.setSize(innerWidth,innerHeight);camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();}window.addEventListener('resize',resize);resize();enterRoom(state.room,true);$('loading').hidden=true;
function move(dt){let dx=0,dz=0;if(keys.has('z')||keys.has('w')||keys.has('arrowup'))dz--;if(keys.has('s')||keys.has('arrowdown'))dz++;if(keys.has('q')||keys.has('a')||keys.has('arrowleft'))dx--;if(keys.has('d')||keys.has('arrowright'))dx++;if(dx||dz)destination=null;const clickMoving=!!destination;walking=!!(dx||dz)||clickMoving;if(walking){const len=Math.hypot(dx,dz)||1;dx/=len;dz/=len;const a=Math.atan2(camera.position.x,camera.position.z);let vx=(dx*Math.cos(a)+dz*Math.sin(a))*4.7*dt,vz=(-dx*Math.sin(a)+dz*Math.cos(a))*4.7*dt;if(destination){const tx=destination.x-hero.position.x,tz=destination.z-hero.position.z,d=Math.hypot(tx,tz);if(d<.18){destination=null;vx=vz=0;}else{vx=tx/d*Math.min(d,4.7*dt);vz=tz/d*Math.min(d,4.7*dt);}}let nx=Math.max(-10.2,Math.min(10.2,hero.position.x+vx)),nz=Math.max(-7,Math.min(8,hero.position.z+vz));const clear=(x,z)=>!colliders.some(c=>c.w?(Math.abs(x-c.x)<c.w/2+.3&&Math.abs(z-c.z)<c.d/2+.3):Math.hypot(x-c.x,z-c.z)<c.r+.3);if(clear(nx,hero.position.z))hero.position.x=nx;if(clear(hero.position.x,nz))hero.position.z=nz;let angle=Math.atan2(vx,vz),diff=Math.atan2(Math.sin(angle-body.rotation.y),Math.cos(angle-body.rotation.y));body.rotation.y+=diff*Math.min(1,dt*12);}
 if(jumpY>0||jumpV>0){jumpV-=15*dt;jumpY=Math.max(0,jumpY+jumpV*dt);if(!jumpY)jumpV=0;}hero.position.y=jumpY;
 near=null;let best=Infinity;for(const o of objects){const d=Math.hypot(hero.position.x-o.x,hero.position.z-o.z);o.ring.visible=false;if(!o.disabled&&d<o.radius&&d<best){best=d;near=o;}}if(near){near.ring.visible=true;$('interaction').hidden=false;$('interaction').querySelector('span').textContent=near.title;$('interaction').querySelector('kbd').textContent=state.wand&&near.id.startsWith('target')?'F':'E';}else $('interaction').hidden=true;
}
function frame(){const dt=Math.min(clock.getDelta(),.04),t=clock.elapsedTime;if(started&&!paused)move(dt);else walking=false;legs.forEach((l,i)=>l.rotation.x=walking?Math.sin(t*11+i*Math.PI)*.6:0);arms.forEach((a,i)=>a.rotation.x=walking?-Math.sin(t*11+i*Math.PI)*.45:Math.sin(t*1.5)*.025);scarf.rotation.x=Math.sin(t*4)*.12;body.position.y=walking?Math.abs(Math.sin(t*11))*.035:Math.sin(t*2)*.018;shadow.position.set(hero.position.x,.11,hero.position.z);shadow.scale.setScalar(1-jumpY*.18);
 for(const a of animated){if(a.m){a.m.position.y=a.y+Math.sin(t*1.8+a.m.position.x)*.1;a.m.rotation.y+=dt*.35;}if(a.dust)a.dust.rotation.y=t*.012;}
 for(let i=projectiles.length-1;i>=0;i--){const p=projectiles[i];if(!paused)p.t+=dt*2.5;p.m.position.lerpVectors(p.start,p.end,Math.min(p.t,1));if(p.t>=1){if(p.target)hitTarget(p.target);scene.remove(p.m);p.m.geometry.dispose();projectiles.splice(i,1);}}
 pulse=Math.max(0,pulse-dt);if(door&&[state.balance,state.light,state.final][state.room])door.fill.material.opacity=.32+Math.sin(t*2)*.08+pulse*.2;
 const portrait=innerWidth/innerHeight<.85;let targetPos,targetLook;if(!started){targetPos=new THREE.Vector3(22,19,26);targetLook=new THREE.Vector3(1,0,0);}else if(portrait){targetPos=new THREE.Vector3(hero.position.x*.45+16,26,hero.position.z*.45+24);targetLook=new THREE.Vector3(hero.position.x*.45,.4,hero.position.z*.45);}else{targetPos=new THREE.Vector3(16+hero.position.x*.16,22,27+hero.position.z*.16);targetLook=new THREE.Vector3(hero.position.x*.16,0,hero.position.z*.16);}camera.position.lerp(targetPos,Math.min(1,dt*2));camera.lookAt(targetLook);renderer.render(scene,camera);requestAnimationFrame(frame);}
frame();
